mapper.select:
SELECT
(SELECT MAX(sbc.round_no) FROM settlement_block sbc
JOIN block bc ON bc.block_id = sbc.block_id
JOIN step stc ON stc.step_id = bc.step_id
WHERE stc.project_id = target.project_id
AND sbc.type = #{type}
AND sbc.settle_id != #{settleId}
) AS maxRoundNo,
(SELECT sbt.total_amount FROM settlement_block sbt
JOIN block bt ON bt.block_id = sbt.block_id
JOIN step stt ON stt.step_id = bt.step_id
WHERE stt.project_id = target.project_id
AND sbt.type = #{type}
AND sbt.settle_id != #{settleId}
AND sbt.total_amount IS NOT NULL
AND sbt.deleted_at IS NULL
ORDER BY (sbt.status != 'PENDING') DESC, sbt.settle_id ASC
LIMIT 1
) AS recommendedTotalAmount
FROM (
SELECT st0.project_id AS project_id
FROM settlement_block sb0
JOIN block b0 ON b0.block_id = sb0.block_id
JOIN step st0 ON st0.step_id = b0.step_id
WHERE sb0.settle_id = #{settleId}
) target
